package access

import (
	"maps"
	"slices"
	"testing"
)

// TestViewerConstructors pins each constructor's exact scope shape: which
// scopes carry the unrestricted Admin flag, which carry a user id + visible
// set, and that User's set and mutes arrive intact (field-level assertions,
// not struct equality, so a failure names the drifted field).
func TestViewerConstructors(t *testing.T) {
	ids := []int64{1, 3, 7}
	mutes := map[string]bool{"tmdb": true, "tvparser": false}

	t.Run("System", func(t *testing.T) {
		v := System()
		if !v.Admin {
			t.Fatal("System().Admin = false, want true (see-all scope)")
		}
		if v.UserID != 0 {
			t.Fatalf("System().UserID = %d, want 0 (legacy slot)", v.UserID)
		}
		if len(v.VisibleLibraryIDs) != 0 || len(v.ChainMutes) != 0 {
			t.Fatalf("System() = %+v, want no visible set and no mutes", v)
		}
	})

	t.Run("Admin", func(t *testing.T) {
		v := Admin()
		if !v.Admin {
			t.Fatal("Admin().Admin = false, want true (see-all scope)")
		}
		if v.UserID != 0 {
			t.Fatalf("Admin().UserID = %d, want 0 (ledger slot 0)", v.UserID)
		}
		if len(v.VisibleLibraryIDs) != 0 || len(v.ChainMutes) != 0 {
			t.Fatalf("Admin() = %+v, want no visible set and no mutes", v)
		}
	})

	t.Run("User", func(t *testing.T) {
		v := User(42, ids, mutes)
		if v.Admin {
			t.Fatal("User(42, …).Admin = true, want false (scoped principal)")
		}
		if v.UserID != 42 {
			t.Fatalf("User(42, …).UserID = %d, want 42", v.UserID)
		}
		if !slices.Equal(v.VisibleLibraryIDs, ids) {
			t.Fatalf("User visible set = %v, want %v", v.VisibleLibraryIDs, ids)
		}
		if len(v.ChainMutes) != len(mutes) {
			t.Fatalf("User chain mutes = %v, want %v", v.ChainMutes, mutes)
		}
		for pluginID, muted := range mutes {
			if v.ChainMutes[pluginID] != muted {
				t.Fatalf("User mute[%s] = %t, want %t", pluginID, v.ChainMutes[pluginID], muted)
			}
		}
	})

	t.Run("LegacyDevice", func(t *testing.T) {
		// Admin=true is the deliberate discriminator: LegacyDevice must never
		// collapse to the zero Viewer — the fail-closed law would then hide
		// everything from unbound devices, not just scope them.
		v := LegacyDevice()
		if !v.Admin {
			t.Fatal("LegacyDevice().Admin = false, want true (see-all posture)")
		}
		if v.UserID != 0 {
			t.Fatalf("LegacyDevice().UserID = %d, want 0", v.UserID)
		}
		if len(v.VisibleLibraryIDs) != 0 || len(v.ChainMutes) != 0 {
			t.Fatalf("LegacyDevice() = %+v, want no visible set and no mutes", v)
		}
	})

	t.Run("UserFromNilInputs", func(t *testing.T) {
		v := User(7, nil, nil)
		if v.UserID != 7 || v.Admin {
			t.Fatalf("User(7, nil, nil) = %+v, want UserID 7, unprivileged", v)
		}
		if len(v.VisibleLibraryIDs) != 0 {
			t.Fatalf("User(7, nil, nil) visible set = %v, want empty", v.VisibleLibraryIDs)
		}
		if len(v.ChainMutes) != 0 {
			t.Fatalf("User(7, nil, nil) chain mutes = %v, want empty", v.ChainMutes)
		}
	})
}

// TestViewerZeroValueHidesAll pins the fail-closed floor (doc.go): the bare
// zero Viewer carries no visibility, no mutes, no user id, and no Admin
// flag — every consumer (the store's visibility fragment, the ctx carrier)
// may rely on a Viewer that arrived unset hiding everything.
func TestViewerZeroValueHidesAll(t *testing.T) {
	var v Viewer
	if v.Admin {
		t.Fatal("zero Viewer.Admin = true, want false (unrestricted scope is always an explicit, constructed decision)")
	}
	if v.UserID != 0 {
		t.Fatalf("zero Viewer.UserID = %d, want 0", v.UserID)
	}
	if len(v.VisibleLibraryIDs) != 0 {
		t.Fatalf("zero Viewer.VisibleLibraryIDs = %v, want nil/empty (fail closed)", v.VisibleLibraryIDs)
	}
	if len(v.ChainMutes) != 0 {
		t.Fatalf("zero Viewer.ChainMutes = %v, want nil/empty", v.ChainMutes)
	}
}

// TestViewerCopyOnRead pins the copy-on-read contract (doc.go): every
// constructor returns a Viewer whose slice/map fields are fresh copies of
// the caller's inputs — mutating what the caller holds after construction
// never changes the Viewer in circulation.
func TestViewerCopyOnRead(t *testing.T) {
	t.Run("User", func(t *testing.T) {
		ids := []int64{1, 3, 7}
		mutes := map[string]bool{"tmdb": true, "tvparser": false}
		wantIDs := append([]int64(nil), ids...)
		wantMutes := maps.Clone(mutes)

		v := User(42, ids, mutes)

		// Mutate the caller's slice after User(...): both an element write
		// and an append must leave the Viewer untouched.
		ids[0] = 999
		ids = append(ids, 4)
		if !slices.Equal(v.VisibleLibraryIDs, wantIDs) {
			t.Fatalf("after caller slice mutation, VisibleLibraryIDs = %v, want %v", v.VisibleLibraryIDs, wantIDs)
		}

		// Mutate the caller's map after User(...): flip an existing entry
		// and add a new one — the Viewer's mutes must not move.
		mutes["tmdb"] = false
		mutes["fanart"] = true
		if !maps.Equal(v.ChainMutes, wantMutes) {
			t.Fatalf("after caller map mutation, ChainMutes = %v, want %v", v.ChainMutes, wantMutes)
		}
	})

	// The no-input constructors have nothing to alias — their slice/map
	// fields must still be empty, so no caller-held memory can reach a
	// Viewer through them.
	t.Run("NoInputConstructors", func(t *testing.T) {
		for name, v := range map[string]Viewer{
			"System":       System(),
			"Admin":        Admin(),
			"LegacyDevice": LegacyDevice(),
		} {
			if len(v.VisibleLibraryIDs) != 0 {
				t.Fatalf("%s.VisibleLibraryIDs = %v, want empty", name, v.VisibleLibraryIDs)
			}
			if len(v.ChainMutes) != 0 {
				t.Fatalf("%s.ChainMutes = %v, want empty", name, v.ChainMutes)
			}
		}
	})
}
